import { Question } from "@/types";

// DA-252 lecture-wise practice bank. Fresh questions (distinct from the 200
// subject-wise questions in da-252.ts), each prepared directly from the DA-252
// Theory Notes source and tagged to its lecture so the lecture-wise practice
// (/practice/da-252/lecture-N) is populated for every lecture.
export const da252LectureQuestions: Question[] = [
  // ── Lecture 1: Introduction to Surveying ──
  { id: "d252l_001", subject: "da-252", lecture: "lecture-1", lectureNo: 1, question: "Surveys carried out for navigation on seas, lakes and rivers are classified (by nature of the field) as:", options: ["Land surveys", "Astronomical surveys", "Marine surveys", "Cadastral surveys"], correct: 2, explanation: "By the nature of the field, surveys are land, marine (navigation) and astronomical; marine surveys deal with bodies of water.", difficulty: "easy" },
  { id: "d252l_002", subject: "da-252", lecture: "lecture-1", lectureNo: 1, question: "A geological survey, classified by the object of the survey, is carried out for:", options: ["Plotting contour lines", "Measuring magnetic bearings applied in plane-table traversing", "Determining the different strata in the earth's crust", "Designing greenhouses"], correct: 2, explanation: "Classified by object of survey, a geological survey is done to determine the different strata in the earth's crust.", difficulty: "medium" },
  { id: "d252l_003", subject: "da-252", lecture: "lecture-1", lectureNo: 1, question: "Triangulation surveys and traverse surveys are a classification of surveys based on the:", options: ["Instrument employed", "Object of the survey", "Nature of the field", "Method employed"], correct: 3, explanation: "Classification based on the method employed includes triangulation surveys and traverse surveys.", difficulty: "medium" },
  { id: "d252l_004", subject: "da-252", lecture: "lecture-1", lectureNo: 1, question: "On a plan, the distances shown are:", options: ["Only vertical distances", "Slope distances", "Both horizontal and vertical distances", "Only horizontal distances"], correct: 3, explanation: "A plan is the representation of the ground projected on a horizontal plane; on a plan only horizontal distances are shown.", difficulty: "easy" },
  { id: "d252l_005", subject: "da-252", lecture: "lecture-1", lectureNo: 1, question: "Chain survey, theodolite survey, tacheometric survey and compass survey are classifications of survey based on the:", options: ["Object of survey", "Instrument employed", "Nature of the field", "Method employed"], correct: 1, explanation: "Classification based on the instrument employed includes chain, theodolite, tacheometric, compass, plane table and photographic/aerial surveys.", difficulty: "medium" },
  { id: "d252l_006", subject: "da-252", lecture: "lecture-1", lectureNo: 1, question: "The planning of engineering projects such as highways, railways, irrigation and water supply is based upon:", options: ["Guesswork only", "Soil testing only for flow (surface) irrigation systems", "Elaborate and complete surveys", "Weather forecasts"], correct: 2, explanation: "The planning of all large engineering and construction projects (highways, railways, irrigation, water supply) is based upon elaborate and complete surveys.", difficulty: "easy" },
  { id: "d252l_007", subject: "da-252", lecture: "lecture-1", lectureNo: 1, question: "The survey work of taking measurements in the field is called field work; the survey is then divided into field work and:", options: ["Marketing", "Office work (computing and drawing)", "Soil testing", "Crop planning applied in plane-table traversing"], correct: 1, explanation: "Survey is divided into field work (taking measurements) and office work (computing and drawing the plan).", difficulty: "easy" },

  // ── Lecture 2: Measurement of Distance ──
  { id: "d252l_008", subject: "da-252", lecture: "lecture-2", lectureNo: 2, question: "The four main direct methods of measuring distance are pacing, the instrumental method, chaining and:", options: ["Levelling", "Triangulation", "Judging distance / time measurement", "Photographic survey as entered in the surveyor field book"], correct: 2, explanation: "The four direct methods of measuring distance are pacing, instrumental methods, judging distance & time measurement, and chaining.", difficulty: "medium" },
  { id: "d252l_009", subject: "da-252", lecture: "lecture-2", lectureNo: 2, question: "The length of a person's pace depends on the person, the ground, the speed of pacing and the:", options: ["Time of day", "Slope of the country", "Wind direction measured along the main chain line", "Soil colour"], correct: 1, explanation: "The length of a pace depends on the person, the ground, the speed of pacing and the slope of the country.", difficulty: "medium" },
  { id: "d252l_010", subject: "da-252", lecture: "lecture-2", lectureNo: 2, question: "In the pacing method, the distance of a line is obtained by multiplying the number of paces by the:", options: ["Number of arrows", "Magnetic bearing", "Width of the chain used while plotting the map to scale", "Average length of one pace"], correct: 3, explanation: "In pacing, distance = number of paces between the two points x the average length of one pace.", difficulty: "easy" },
  { id: "d252l_011", subject: "da-252", lecture: "lecture-2", lectureNo: 2, question: "Determining distances roughly by knowing the average time taken per km at walk and the total time taken is the method of:", options: ["Judging distance and time measurement", "Chaining", "Odometer", "Optical square applied in plane-table traversing"], correct: 0, explanation: "Judging distance and time measurement gives very approximate results (as in reconnaissance) using the average time taken per km and the total time taken.", difficulty: "medium" },
  { id: "d252l_012", subject: "da-252", lecture: "lecture-2", lectureNo: 2, question: "Where great accuracy is required in chaining, instead of a chain the surveyor uses a:", options: ["Ranging rod", "Cross-staff", "Plumb bob", "Steel tape"], correct: 3, explanation: "Ordinarily a chain is used for chaining, but where great accuracy is required a steel tape is invariably used.", difficulty: "easy" },
  { id: "d252l_013", subject: "da-252", lecture: "lecture-2", lectureNo: 2, question: "A passometer is usually carried:", options: ["In the pocket or tied to the leg", "On a tripod", "On the chain", "On a ranging rod measured along the main chain line"], correct: 0, explanation: "A passometer is a watch-like instrument carried in the pocket or tied to the leg that records the paces as the person walks.", difficulty: "easy" },
  { id: "d252l_014", subject: "da-252", lecture: "lecture-2", lectureNo: 2, question: "Pacing as a method of measuring distance is most useful for:", options: ["High-precision base-line work applied in plane-table traversing used while plotting the map to scale", "Greenhouse climate control", "Quick, rough preliminary surveys and rough checks of other measurements", "Drip emitter design"], correct: 2, explanation: "Pacing is mostly employed in preliminary surveys and explorations and to roughly check distances measured by other means.", difficulty: "easy" },

  // ── Lecture 3: Chains, Tapes & Survey Accessories ──
  { id: "d252l_015", subject: "da-252", lecture: "lecture-3", lectureNo: 3, question: "Eighty Gunter's chains are equal to:", options: ["1 mile", "1 furlong", "1 acre", "1 kilometre"], correct: 0, explanation: "For Gunter's chain: 10 chains = 1 furlong, 80 chains = 1 mile, and 10 square chains = 1 acre.", difficulty: "medium" },
  { id: "d252l_016", subject: "da-252", lecture: "lecture-3", lectureNo: 3, question: "Each link of a Gunter's chain is equal to:", options: ["1 ft", "0.66 ft", "0.2 m applied in plane-table traversing", "33 ft"], correct: 1, explanation: "Gunter's chain is 66 ft long with 100 links, so each link equals 0.66 ft.", difficulty: "medium" },
  { id: "d252l_017", subject: "da-252", lecture: "lecture-3", lectureNo: 3, question: "The metallic tape used in surveying is made of cotton or linen reinforced with:", options: ["Steel ribbon as entered in the surveyor field book", "Fine brass or copper wires", "Glass fibre", "Nylon thread"], correct: 1, explanation: "The metallic tape is made of cotton or linen reinforced with fine brass or copper wires, which prevents stretching of the fibres.", difficulty: "medium" },
  { id: "d252l_018", subject: "da-252", lecture: "lecture-3", lectureNo: 3, question: "The synthetic tape used in surveying is manufactured of:", options: ["Steel measured along the main chain line", "Invar", "Linen", "Glass fibre with a PVC coating"], correct: 3, explanation: "Synthetic tapes are manufactured of glass fibre having a PVC coating, graduated every 10 mm; they hold their length well and suit short lengths.", difficulty: "medium" },
  { id: "d252l_019", subject: "da-252", lecture: "lecture-3", lectureNo: 3, question: "The ranging rod is provided at its lower end with a pointed metal shoe about:", options: ["1 cm long", "0.2 m long", "1 m long", "15 cm long"], correct: 3, explanation: "Ranging rods have a pointed metal shoe about 15 cm long at the lower end to facilitate fixing them in the ground.", difficulty: "medium" },
  { id: "d252l_020", subject: "da-252", lecture: "lecture-3", lectureNo: 3, question: "A plumb bob in surveying is generally made of:", options: ["Brass with a pointed end", "Wood", "Glass", "Rubber applied in plane-table traversing"], correct: 0, explanation: "A plumb bob consists of a metal weight made of brass with a pointed end, suspended by a string.", difficulty: "easy" },
  { id: "d252l_021", subject: "da-252", lecture: "lecture-3", lectureNo: 3, question: "Wooden pegs used to mark stations are tapered at:", options: ["Both ends", "One end", "Neither end", "The middle"], correct: 1, explanation: "Wooden pegs are made of hard timber and are tapered at one end so they can be driven into the ground.", difficulty: "easy" },

  // ── Lecture 4: Cross-Staff & Optical Square ──
  { id: "d252l_022", subject: "da-252", lecture: "lecture-4", lectureNo: 4, question: "The two common types of cross-staff are the:", options: ["Steel and the invar", "Open and the French", "Single and the double", "Closed and the open impeller"], correct: 1, explanation: "There are two types of cross-staff: the open cross-staff (in common use) and the French cross-staff.", difficulty: "medium" },
  { id: "d252l_023", subject: "da-252", lecture: "lecture-4", lectureNo: 4, question: "In the optical square, the horizontal mirror (H) is:", options: ["Fully silvered", "Absent", "Made of plastic", "Half silvered"], correct: 3, explanation: "In the optical square the horizontal mirror H is half-silvered (upper half plain) while the index mirror I is fully silvered.", difficulty: "hard" },
  { id: "d252l_024", subject: "da-252", lecture: "lecture-4", lectureNo: 4, question: "The optical square is generally a round brass box about:", options: ["1 cm in diameter", "1 m in diameter", "25 cm in diameter", "5 cm in diameter"], correct: 3, explanation: "The optical square is a small, compact hand instrument - generally a round brass box about 5 cm in diameter and 1.25 cm deep.", difficulty: "medium" },
  { id: "d252l_025", subject: "da-252", lecture: "lecture-4", lectureNo: 4, question: "The open cross-staff consists of two parts: the leg and the:", options: ["Graduated ring applied in plane-table traversing", "Mirror box", "Head (four metal arms with vertical slits)", "Foot valve"], correct: 2, explanation: "The open cross-staff consists of the head (four metal arms with vertical slits set at right angles) and the leg (the supporting pole).", difficulty: "medium" },
  { id: "d252l_026", subject: "da-252", lecture: "lecture-4", lectureNo: 4, question: "Compared with the cross-staff, the optical square can be used for locating objects situated at:", options: ["Only very short distances", "No distance at all", "Larger distances", "Only underground"], correct: 2, explanation: "The optical square is more accurate than the cross-staff and can be used for locating objects at larger distances.", difficulty: "medium" },
  { id: "d252l_027", subject: "da-252", lecture: "lecture-4", lectureNo: 4, question: "Besides the cross-staff and optical square, another precise instrument used for setting out right angles is the:", options: ["Plumb bob", "Prism square", "Ranging rod measured along the main chain line", "Arrow"], correct: 1, explanation: "Precise instruments for setting out right angles include the cross-staff, French cross-staff, adjustable cross-staff, optical square and prism square.", difficulty: "medium" },
  { id: "d252l_028", subject: "da-252", lecture: "lecture-4", lectureNo: 4, question: "The open cross-staff is usually mounted for fixing on the ground on a pole about:", options: ["0.2 m long", "5 m long", "1.5 m long", "20 m long"], correct: 2, explanation: "The cross-staff is mounted on a 25 mm diameter pole about 1.5 metre long for fixing on the ground.", difficulty: "medium" },

  // ── Lecture 5: Errors, Ranging & Obstacles ──
  { id: "d252l_029", subject: "da-252", lecture: "lecture-5", lectureNo: 5, question: "A positive cumulative error in chaining makes the measured length:", options: ["Exactly equal to actual", "Less than the actual length", "More than the actual length", "Zero"], correct: 2, explanation: "Cumulative errors occur in the same direction; positive errors make the measured length more than the actual, negative errors make it less.", difficulty: "medium" },
  { id: "d252l_030", subject: "da-252", lecture: "lecture-5", lectureNo: 5, question: "When the end points of a survey line are intervisible and ranging rods are placed in line by direct observation, it is called:", options: ["Indirect ranging", "Direct ranging", "Random ranging", "Reciprocal ranging"], correct: 1, explanation: "Direct ranging is used when the end points are visible from one another; intermediate ranging rods are placed in line by direct observation.", difficulty: "easy" },
  { id: "d252l_031", subject: "da-252", lecture: "lecture-5", lectureNo: 5, question: "To run a line across a wooded field where intermediate stations cannot be fixed, the most suitable method is the:", options: ["Random line method", "Direct ranging", "Plumb bob method measured along the main chain line", "Pacing method"], correct: 0, explanation: "When trees and undergrowth prevent fixing intermediate stations, the method of the random line is most suitable.", difficulty: "hard" },
  { id: "d252l_032", subject: "da-252", lecture: "lecture-5", lectureNo: 5, question: "A hill that blocks the line of sight but still allows the chain to be laid is an obstacle in which:", options: ["Chaining is obstructed but vision is free", "Both chaining and vision are obstructed", "Vision is obstructed but chaining is free", "Neither is obstructed"], correct: 2, explanation: "A rising ground or hill is a case where chaining is free but the vision is obstructed (the ends are not intervisible).", difficulty: "medium" },
  { id: "d252l_033", subject: "da-252", lecture: "lecture-5", lectureNo: 5, question: "One of the duties of the leader (head chainman) during chaining is to:", options: ["Drag the chain forward and insert arrows at the end of each chain", "Pick up the arrows", "Stay at the rear station as entered in the surveyor field book applied in plane-table traversing", "Book the readings"], correct: 0, explanation: "The leader drags the chain forward, inserts arrows at the end of every chain, and obeys the follower's instructions; the follower picks up the arrows.", difficulty: "medium" },
  { id: "d252l_034", subject: "da-252", lecture: "lecture-5", lectureNo: 5, question: "A building that blocks both the chain and the line of sight is an obstacle in which:", options: ["Only vision is obstructed", "Only chaining is obstructed applied in plane-table traversing", "Nothing is obstructed", "Both chaining and vision are obstructed"], correct: 3, explanation: "A building is a typical example where both chaining and vision are obstructed; the line must be prolonged beyond the obstruction.", difficulty: "medium" },
  { id: "d252l_035", subject: "da-252", lecture: "lecture-5", lectureNo: 5, question: "The length of the chain should be tested:", options: ["Before commencing each day's work and at frequent intervals", "Only once a year", "Never", "Only after damage obtained during the reconnaissance survey measured along the main chain line"], correct: 0, explanation: "It is always necessary to check the chain length before commencing each day's work and at frequent intervals, by comparing it with a standard or a steel tape.", difficulty: "easy" },

  // ── Lecture 6: Base Line, Offsets & Field Book ──
  { id: "d252l_036", subject: "da-252", lecture: "lecture-6", lectureNo: 6, question: "The base line in a chain survey should preferably pass through the:", options: ["Edge of the area measured along the main chain line", "Lowest point", "Nearest building", "Centre of the area"], correct: 3, explanation: "The base line is the longest and most important line; it should pass through the centre of the area and be measured very accurately.", difficulty: "medium" },
  { id: "d252l_037", subject: "da-252", lecture: "lecture-6", lectureNo: 6, question: "A tie line is obtained by joining:", options: ["The apex of a triangle to its base obtained during the reconnaissance survey", "Two fixed points on the main survey line", "Two greenhouses", "A station to a pump"], correct: 1, explanation: "A tie (subsidiary) line is obtained by joining two fixed points on the main survey line and is used to locate details; it can also serve as a check line.", difficulty: "medium" },
  { id: "d252l_038", subject: "da-252", lecture: "lecture-6", lectureNo: 6, question: "When a perpendicular offset is set by swinging a tape from the object to the chain line, the base of the perpendicular is the point of:", options: ["Maximum reading on the tape", "The mid-reading", "Minimum reading on the tape", "The first reading"], correct: 2, explanation: "When a perpendicular is set by swinging a tape from the object to the chain line, the point of minimum reading on the tape is the foot (base) of the perpendicular.", difficulty: "hard" },
  { id: "d252l_039", subject: "da-252", lecture: "lecture-6", lectureNo: 6, question: "The neat hand sketch (key plan) prepared during reconnaissance, resembling the plan of the ground, is called the:", options: ["Index sketch", "Field book", "Check line", "Contour map applied in plane-table traversing"], correct: 0, explanation: "During reconnaissance the surveyor prepares a neat hand sketch called an index sketch or key plan, showing boundaries, features, stations and chain lines.", difficulty: "medium" },
  { id: "d252l_040", subject: "da-252", lecture: "lecture-6", lectureNo: 6, question: "In the field book, the chainage lengths are noted in the:", options: ["Central column between two red lines", "Left margin only", "Right margin only", "Top of the page only measured along the main chain line"], correct: 0, explanation: "In the field book, chainage lengths are noted in the central column between two red lines, and offset lengths are written on either side.", difficulty: "medium" },
  { id: "d252l_041", subject: "da-252", lecture: "lecture-6", lectureNo: 6, question: "The check line in a chain survey joins:", options: ["Two stations on the base line only obtained during the reconnaissance survey", "A pump to a canal", "Two greenhouses", "The apex of a triangle to a fixed point on the opposite side"], correct: 3, explanation: "A check (proof) line is a line joining the apex of a triangle to a fixed point on the opposite side, used to check the accuracy of measurement and plotting.", difficulty: "medium" },
  { id: "d252l_042", subject: "da-252", lecture: "lecture-6", lectureNo: 6, question: "Perpendicular offsets are preferred over oblique offsets mainly because they:", options: ["Need expensive instruments as entered in the surveyor field book applied in plane-table traversing", "Can be taken quickly and make plotting and field-book entry easy", "Are less accurate", "Require no chain line"], correct: 1, explanation: "Perpendicular offsets are preferred because they can be taken quickly, do not hamper the survey, and make field-book entry and plotting easy.", difficulty: "easy" },

  // ── Lecture 7: Triangulation & Area Measurement ──
  { id: "d252l_043", subject: "da-252", lecture: "lecture-7", lectureNo: 7, question: "The two general methods of measuring areas in surveying are triangulation and:", options: ["Levelling", "Pacing", "Traversing", "Contouring"], correct: 2, explanation: "The two general methods of measuring areas are triangulation and traversing.", difficulty: "easy" },
  { id: "d252l_044", subject: "da-252", lecture: "lecture-7", lectureNo: 7, question: "In traversing, the lengths of the connected lines and their directions are measured respectively by:", options: ["Level and staff", "Tape and tape", "Compass and chain", "Chain and compass"], correct: 3, explanation: "In traversing, the lengths of the connected lines are measured by chain and their directions by compass (or theodolite).", difficulty: "medium" },
  { id: "d252l_045", subject: "da-252", lecture: "lecture-7", lectureNo: 7, question: "In chain triangulation, the total area is obtained by:", options: ["Measuring only one side of the whole area measured along the main chain line", "Measuring the perimeter only", "Counting the number of arrows", "Computing the area of each triangle and adding them together"], correct: 3, explanation: "The whole area is divided into triangles; the area of each individual triangle is computed and added to get the total area.", difficulty: "medium" },
  { id: "d252l_046", subject: "da-252", lecture: "lecture-7", lectureNo: 7, question: "Triangulation refers to a system of surveying in which one line is measured with a chain and the three angles are measured by:", options: ["A plumb bob", "A ranging rod obtained during the reconnaissance survey", "Compass or theodolite", "An odometer"], correct: 2, explanation: "Triangulation is a system in which one line is measured with a chain and all three angles are measured correctly by compass or theodolite.", difficulty: "medium" },
  { id: "d252l_047", subject: "da-252", lecture: "lecture-7", lectureNo: 7, question: "When only the sides of the triangles are measured and no angular measurement is taken, the method is called:", options: ["Triangulation", "Theodolite traversing", "Tacheometry", "Levelling"], correct: 0, explanation: "When only the sides of the triangles are directly measured and no angles are taken, it is called triangulation (chain surveying).", difficulty: "hard" },
  { id: "d252l_048", subject: "da-252", lecture: "lecture-7", lectureNo: 7, question: "A major purpose of surveying in agriculture is to measure the:", options: ["Soil pH", "Seed germination", "Insect population measured along the main chain line as entered in the surveyor field book", "Area of farms, plots, command area of tube wells and canals"], correct: 3, explanation: "One of the main purposes of surveying is to measure the area of an agricultural farm, plots, command area of tube wells, canals, etc.", difficulty: "easy" },

  // ── Lecture 8: Compass Surveying & Prismatic Compass ──
  { id: "d252l_049", subject: "da-252", lecture: "lecture-8", lectureNo: 8, question: "When triangulation is not possible, the surveying method used (lengths and directions measured) is:", options: ["Traversing", "Levelling", "Contouring", "Tacheometry"], correct: 0, explanation: "When triangulation is not possible, traversing is used - a series of connected lines whose lengths and directions are measured.", difficulty: "medium" },
  { id: "d252l_050", subject: "da-252", lecture: "lecture-8", lectureNo: 8, question: "In the prismatic compass, the magnetic needle is attached to a graduated ring made of:", options: ["Iron", "Brass obtained during the reconnaissance survey", "Aluminium", "Steel"], correct: 2, explanation: "In the prismatic compass the pivot balances the magnetic needle, which is attached to a graduated aluminium ring.", difficulty: "medium" },
  { id: "d252l_051", subject: "da-252", lecture: "lecture-8", lectureNo: 8, question: "In the prismatic compass, two sun glasses are provided to:", options: ["Level the instrument", "Protect the needle from dust", "Measure distance", "Observe bright objects"], correct: 3, explanation: "Two sun glasses are provided in the prismatic compass to observe bright objects; a glass cover protects the needle from dust.", difficulty: "medium" },
  { id: "d252l_052", subject: "da-252", lecture: "lecture-8", lectureNo: 8, question: "The object vane of a prismatic compass carries a central vertical:", options: ["Mirror applied in plane-table traversing", "Prism", "Magnet", "Horse hair for sighting the object"], correct: 3, explanation: "The object vane is an open frame with a central vertical horse hair for sighting the object.", difficulty: "medium" },
  { id: "d252l_053", subject: "da-252", lecture: "lecture-8", lectureNo: 8, question: "The tripod stand of a prismatic compass uses a ball-and-socket joint mainly to:", options: ["Measure bearings as entered in the surveyor field book", "Level the compass quickly", "Carry the prism", "Store the arrows"], correct: 1, explanation: "The tripod stand consists of a ball-and-socket joint which helps in levelling the compass quickly.", difficulty: "easy" },
  { id: "d252l_054", subject: "da-252", lecture: "lecture-8", lectureNo: 8, question: "In the prismatic compass, the device provided to stop the oscillations of the graduated ring so a reading can be taken is the:", options: ["Object vane", "Brake pin", "Sun glass", "Pivot"], correct: 1, explanation: "A brake pin is provided to stop the oscillations of the graduated ring, facilitating the reading.", difficulty: "hard" },
  { id: "d252l_055", subject: "da-252", lecture: "lecture-8", lectureNo: 8, question: "An open traverse is one in which the survey lines:", options: ["Form a closed polygon obtained during the reconnaissance survey", "Are all perpendicular", "Do not form a closed polygon", "Are all equal"], correct: 2, explanation: "An open traverse is a traverse in which the sides do not form a closed polygon; a closed traverse forms a closed figure.", difficulty: "easy" },

  // ── Lecture 9: Meridians, Bearings & Local Attraction ──
  { id: "d252l_056", subject: "da-252", lecture: "lecture-9", lectureNo: 9, question: "Any convenient direction assumed as a meridian for measuring bearings of survey lines is the:", options: ["Arbitrary meridian", "Magnetic meridian used while plotting the map to scale", "True meridian", "Grid meridian"], correct: 0, explanation: "An arbitrary meridian is any convenient direction assumed as a meridian for measuring the bearings of survey lines.", difficulty: "easy" },
  { id: "d252l_057", subject: "da-252", lecture: "lecture-9", lectureNo: 9, question: "A bearing is defined as the horizontal angle made by a survey line with reference to the:", options: ["Chain line", "Horizon", "Base line", "Meridian"], correct: 3, explanation: "A bearing is the horizontal angle made by the survey line with reference to the meridian.", difficulty: "easy" },
  { id: "d252l_058", subject: "da-252", lecture: "lecture-9", lectureNo: 9, question: "To convert a whole circle bearing between 180° and 270° to a reduced bearing, the rule is RB =:", options: ["WCB", "WCB - 180° (S.W. quadrant)", "180° - WCB as entered in the surveyor field book", "360° - WCB"], correct: 1, explanation: "For WCB between 180° and 270°, RB = WCB - 180° and lies in the S.W. quadrant.", difficulty: "hard" },
  { id: "d252l_059", subject: "da-252", lecture: "lecture-9", lectureNo: 9, question: "If the fore bearing of a line is 200°, its back bearing is:", options: ["120°", "380°", "200°", "20°"], correct: 3, explanation: "BB = FB ± 180°. Since FB (200°) is greater than 180°, BB = FB - 180° = 200° - 180° = 20°.", difficulty: "medium" },
  { id: "d252l_060", subject: "da-252", lecture: "lecture-9", lectureNo: 9, question: "Quadrantal bearings are reckoned from 0° to 90° in:", options: ["A full circle", "Only the north-east quadrant", "Each of the four quadrants", "Only the south-west quadrant"], correct: 2, explanation: "In the quadrantal system the angle at a station is divided into four quadrants and the bearing is reckoned from 0° to 90° in each quadrant, from N or S towards E or W.", difficulty: "medium" },
  { id: "d252l_061", subject: "da-252", lecture: "lecture-9", lectureNo: 9, question: "Quadrantal bearings are also known as:", options: ["Reduced bearings", "Whole circle bearings", "Magnetic bearings", "Back bearings"], correct: 0, explanation: "Quadrantal bearings are also called reduced bearings (RB).", difficulty: "easy" },
  { id: "d252l_062", subject: "da-252", lecture: "lecture-9", lectureNo: 9, question: "The true meridian is the line of intersection of the earth's surface formed by a plane passing through:", options: ["The north and south poles and the given place", "The east and west points as entered in the surveyor field book", "Any two stations", "The sun and the place"], correct: 0, explanation: "The true meridian is the line of intersection of the earth's surface formed by a plane passing through the north and south poles and the given place.", difficulty: "medium" },

  // ── Lecture 10: Soil & Water Conservation - Erosion ──
  { id: "d252l_063", subject: "da-252", lecture: "lecture-10", lectureNo: 10, question: "In soil erosion, the transporting agents are flowing water, rain splash and:", options: ["Earthworms", "Sunlight", "Roots", "Wind"], correct: 3, explanation: "The agents causing erosion are wind and water; the transporting agents are flowing water, rain splash and wind.", difficulty: "easy" },
  { id: "d252l_064", subject: "da-252", lecture: "lecture-10", lectureNo: 10, question: "Ravines, which are deep and wide gullies, are typically found in:", options: ["Sandy desert soils obtained during the reconnaissance survey", "Deep alluvial soils", "Rocky hills", "Black cotton soils"], correct: 1, explanation: "Ravines are the manifestation of a prolonged process of gully erosion and are typically found in deep alluvial soils.", difficulty: "medium" },
  { id: "d252l_065", subject: "da-252", lecture: "lecture-10", lectureNo: 10, question: "Suspension in wind erosion usually accounts for not more than about:", options: ["15% of the total movement", "50% of the total movement", "70% of the total movement", "95% of the total movement"], correct: 0, explanation: "Suspension (movement of fine dust particles smaller than 0.1 mm by floating in air) usually accounts for not more than about 15% of the total wind-erosion movement.", difficulty: "medium" },
  { id: "d252l_066", subject: "da-252", lecture: "lecture-10", lectureNo: 10, question: "The process of wind erosion consists of three phases: initiation of movement, transportation and:", options: ["Detachment", "Deposition", "Infiltration", "Evaporation"], correct: 1, explanation: "The process of wind erosion consists of three phases: initiation of movement, transportation and deposition.", difficulty: "medium" },
  { id: "d252l_067", subject: "da-252", lecture: "lecture-10", lectureNo: 10, question: "The minimum wind velocity necessary to initiate the movement of most erodible soil particles (about 0.1 mm) at a height of 30.5 cm is about:", options: ["16 km/hr", "1 km/hr", "50 km/hr", "100 km/hr"], correct: 0, explanation: "The minimum wind velocity needed to initiate movement of most erodible particles (about 0.1 mm) is about 16 km/hr at a height of 30.5 cm.", difficulty: "hard" },
  { id: "d252l_068", subject: "da-252", lecture: "lecture-10", lectureNo: 10, question: "In India, the desert formed mainly by blown (deposited) sand is the:", options: ["Thar Desert", "Deccan plateau", "Sundarbans", "Western Ghats"], correct: 0, explanation: "In India about 33 m.ha is affected by wind erosion; the Thar Desert is formed mainly by blown-in sand.", difficulty: "easy" },
  { id: "d252l_069", subject: "da-252", lecture: "lecture-10", lectureNo: 10, question: "Geological (normal) erosion is described as a process that is:", options: ["Very rapid and destructive on wind-eroded sandy soils", "Very slow and in equilibrium with soil formation", "Caused only by man", "Limited to deserts"], correct: 1, explanation: "Geological (normal) erosion is in equilibrium with the soil-forming process, occurs under undisturbed natural vegetation and is a very slow process.", difficulty: "medium" },

  // ── Lecture 11: Crop-Water Management - Delta & Duty ──
  { id: "d252l_070", subject: "da-252", lecture: "lecture-11", lectureNo: 11, question: "The crop period of a crop is the time between:", options: ["First and last watering", "Sowing and harvesting of the crop", "Two irrigations", "Germination and flowering applied in plane-table traversing"], correct: 1, explanation: "Crop period is the time between the sowing of a crop and its harvesting; for practical purposes it is taken as the same as the base period but is slightly greater.", difficulty: "medium" },
  { id: "d252l_071", subject: "da-252", lecture: "lecture-11", lectureNo: 11, question: "Duty of water increases as one moves from the head of the main canal towards the branches, mainly because of:", options: ["Transmission losses in the channels", "Increased rainfall in canal-irrigated command areas", "Higher crop demand", "Lower temperature"], correct: 0, explanation: "Duty varies from point to point; it increases as one moves downstream from the head of the main canal to the branches, due to the transmission losses in the channels.", difficulty: "hard" },
  { id: "d252l_072", subject: "da-252", lecture: "lecture-11", lectureNo: 11, question: "Delta of a crop is expressed in units of:", options: ["Depth (cm or inches)", "Hectare/cumec within the culturable command area", "Litres/second", "Days"], correct: 0, explanation: "Delta is the total depth of water required during the base period and is expressed in depth units (cm or inches).", difficulty: "easy" },
  { id: "d252l_073", subject: "da-252", lecture: "lecture-11", lectureNo: 11, question: "If 1 cumec of water flowing continuously for the base period matures 100 hectares, the duty of that crop is:", options: ["1 hectare/cumec", "100 hectare/cumec", "100 cumec/hectare", "8.64 hectare/cumec"], correct: 1, explanation: "By definition, if 1 cumec flowing continuously for the base period matures 100 hectares, the duty is 100 hectare/cumec.", difficulty: "medium" },
  { id: "d252l_074", subject: "da-252", lecture: "lecture-11", lectureNo: 11, question: "Knowing the total available water at the head of a main canal and the overall duty, a surveyor can work out the:", options: ["Area that can be irrigated", "Soil pH", "Insect threshold", "Greenhouse temperature for flow (surface) irrigation systems"], correct: 0, explanation: "Knowing the total available water at the canal head and the overall duty, the area that can be irrigated can be worked out - this is the importance of duty in designing canal systems.", difficulty: "medium" },
  { id: "d252l_075", subject: "da-252", lecture: "lecture-11", lectureNo: 11, question: "Useful rainfall is one of the factors on which the duty of water depends, along with type of crop, climate, soil and:", options: ["Wind direction", "Efficiency of the cultivation method", "Colour of the soil", "Length of the chain over the full base period of the crop"], correct: 1, explanation: "Duty depends on the type of crop, climate and season, useful rainfall, type of soil and the efficiency of the cultivation method.", difficulty: "medium" },

  // ── Lecture 12: Water Measurement Devices ──
  { id: "d252l_076", subject: "da-252", lecture: "lecture-12", lectureNo: 12, question: "The three commonly used methods of measuring water are the volumetric method, the velocity-area method and the use of:", options: ["A ranging rod in canal-irrigated command areas", "A plumb bob", "Measuring structures", "An odometer"], correct: 2, explanation: "The commonly used methods of measuring water are the volumetric method, the velocity-area method (float, current-meter), and measuring structures such as weir, orifice and Parshall flume.", difficulty: "medium" },
  { id: "d252l_077", subject: "da-252", lecture: "lecture-12", lectureNo: 12, question: "If a 210-litre barrel is filled in 30 seconds, the discharge (by the volumetric method) is:", options: ["0.7 litres/second", "70 litres/second", "7 litres/second", "210 litres/second"], correct: 2, explanation: "Discharge = volume / time = 210 litres / 30 s = 7 litres per second (lps).", difficulty: "medium" },
  { id: "d252l_078", subject: "da-252", lecture: "lecture-12", lectureNo: 12, question: "In the float method, the surface velocity of a stream is always:", options: ["Higher than the average velocity", "Lower than the average velocity obtained during the reconnaissance survey", "Equal to the average velocity", "Zero"], correct: 0, explanation: "The surface velocity measured by a float is always higher than the average stream velocity, so it is multiplied by about 0.85 to get the average.", difficulty: "medium" },
  { id: "d252l_079", subject: "da-252", lecture: "lecture-12", lectureNo: 12, question: "A large quantity of water present in a reservoir is most suitably measured in:", options: ["Litres per second", "Hectare-cm", "Cubic metres", "Kg/cm2"], correct: 2, explanation: "Volume of water at rest is measured in litres, ha-cm, m3, etc.; a large quantity in a reservoir is suitably measured in cubic metres (m3).", difficulty: "easy" },
  { id: "d252l_080", subject: "da-252", lecture: "lecture-12", lectureNo: 12, question: "Discharge (water in motion) is measured in units such as:", options: ["Litres per second or m3/hr", "Hectare-cm", "Cubic metres at rest in canal-irrigated command areas", "Kilograms"], correct: 0, explanation: "Water in motion (discharge) is measured as litres per second (lps), litres per minute (lpm) or m3/hr - the volume passing a section per unit time.", difficulty: "easy" },
  { id: "d252l_081", subject: "da-252", lecture: "lecture-12", lectureNo: 12, question: "The volumetric method of water measurement is best suited for measuring:", options: ["Small discharge flowing through a channel or pipe", "Very large river discharges within the culturable command area", "Reservoir storage", "Rainfall"], correct: 0, explanation: "The volumetric method is the simplest and most accurate and is used to measure a small discharge flowing through a channel or pipe.", difficulty: "easy" },

  // ── Lecture 13: Irrigation - Classification & Surface Methods ──
  { id: "d252l_082", subject: "da-252", lecture: "lecture-13", lectureNo: 13, question: "By culturable command area, a MINOR irrigation project has an irrigated area of:", options: ["More than 10,000 ha", "Less than 2,000 ha", "2,000 to 10,000 ha", "Exactly 5,000 ha"], correct: 1, explanation: "Minor irrigation projects have a CCA of less than 2,000 ha; medium 2,000-10,000 ha; major more than 10,000 ha.", difficulty: "medium" },
  { id: "d252l_083", subject: "da-252", lecture: "lecture-13", lectureNo: 13, question: "A benefit of irrigation is that:", options: ["It always causes waterlogging for flow (surface) irrigation systems", "It reduces the value of land", "It protects people from famine when rainfall is severely deficient", "It breeds mosquitoes"], correct: 2, explanation: "Benefits of irrigation include assured crop growth, protection from famine during deficient rainfall, increased land value, and hydro-power generation.", difficulty: "easy" },
  { id: "d252l_084", subject: "da-252", lecture: "lecture-13", lectureNo: 13, question: "A serious disadvantage of applying excess irrigation water is:", options: ["Better aeration", "Higher infiltration over the full base period of the crop", "Waterlogging and the land becoming alkaline/barren", "Lower salinity"], correct: 2, explanation: "Excess irrigation makes the land alkaline and waterlogged so it becomes infertile and barren; standing water can also breed mosquitoes causing malaria.", difficulty: "medium" },
  { id: "d252l_085", subject: "da-252", lecture: "lecture-13", lectureNo: 13, question: "In the border strip method the transverse (cross) slope must be:", options: ["Steep (more than 5%)", "Zero or negligible", "Exactly 2%", "Unimportant"], correct: 1, explanation: "In border irrigation the longitudinal slope must be uniform and the transverse slope must be zero or negligible (< 0.03%).", difficulty: "hard" },
  { id: "d252l_086", subject: "da-252", lecture: "lecture-13", lectureNo: 13, question: "The slope along furrows in furrow irrigation generally ranges from:", options: ["10 to 20%", "5 to 10%", "0.2 to 2%", "20 to 50%"], correct: 2, explanation: "Slope along furrows may range from 0.2 to 2%; where the land is too steep (>5%), furrows must be on the contour.", difficulty: "medium" },
  { id: "d252l_087", subject: "da-252", lecture: "lecture-13", lectureNo: 13, question: "Water for irrigation taken from a surface reservoir is conveyed to the fields through:", options: ["Canals (running from higher to lower elevation by gravity)", "Pumps only", "Drip emitters only over the full base period of the crop for flow (surface) irrigation systems", "Sprinklers only"], correct: 0, explanation: "Water from surface reservoirs is taken through canals, which run from higher to lower elevations so that water flows by the force of gravity.", difficulty: "easy" },
  { id: "d252l_088", subject: "da-252", lecture: "lecture-13", lectureNo: 13, question: "The check basin method is most commonly used for irrigating crops such as:", options: ["Widely spaced orchard trees for flow (surface) irrigation systems", "Deep-rooted forest trees", "Drip-grown flowers", "Groundnut, finger millet, sorghum and vegetables"], correct: 3, explanation: "The check basin method is most commonly used for crops like groundnut, finger millet, sorghum and vegetables; it suits levelled, fine-textured soils.", difficulty: "medium" },

  // ── Lecture 14: Sprinkler & Drip Irrigation ──
  { id: "d252l_089", subject: "da-252", lecture: "lecture-14", lectureNo: 14, question: "A limitation of sprinkler irrigation is:", options: ["Uneven distribution of water under high wind velocities", "No pump is ever needed", "It cannot be used on field crops", "It eliminates evaporation entirely over the full base period of the crop"], correct: 0, explanation: "Limitations of sprinkler irrigation include uneven water distribution under high winds, higher evaporation losses, higher initial cost and the need for higher water pressure.", difficulty: "medium" },
  { id: "d252l_090", subject: "da-252", lecture: "lecture-14", lectureNo: 14, question: "Center-pivot, traveler and linear-move are examples of which sprinkler category?", options: ["Continuous-move sprinkler systems", "Hand-move (set-move) systems within the culturable command area", "Drip systems", "Surface systems"], correct: 0, explanation: "Sprinkler systems are classified as set-move (hand-move, side-roll, gun-type), solid-set or continuous-move (center-pivot, traveler, linear-move).", difficulty: "hard" },
  { id: "d252l_091", subject: "da-252", lecture: "lecture-14", lectureNo: 14, question: "In subsurface drip irrigation, the emitter discharge rate is generally in the range of:", options: ["8 to 16 L/h", "0.6 to 3 L/h", "50 to 100 L/h", "More than 200 L/h"], correct: 1, explanation: "Subsurface drip emitters have a discharge rate generally in the range of 0.6 to 3 L/h; surface point-source emitters discharge less than 8 L/h.", difficulty: "medium" },
  { id: "d252l_092", subject: "da-252", lecture: "lecture-14", lectureNo: 14, question: "A major limitation of drip irrigation is:", options: ["High weed growth", "It wets the whole field for flow (surface) irrigation systems", "Very high water loss", "Sensitivity of emitters to clogging"], correct: 3, explanation: "Limitations of drip irrigation include sensitivity to emitter clogging, salt accumulation, mechanical damage and the need for high technical skill and filtration.", difficulty: "medium" },
  { id: "d252l_093", subject: "da-252", lecture: "lecture-14", lectureNo: 14, question: "In a drip system, the lateral pipes that carry the drippers are normally made of:", options: ["Rigid PVC over the full base period of the crop", "Steel", "Low-density polyethylene, 10-16 mm diameter", "Concrete"], correct: 2, explanation: "Drip laterals are normally made of LDPE, with internal diameters of 10, 12 and 16 mm; main lines are rigid PVC/HDPE.", difficulty: "medium" },
  { id: "d252l_094", subject: "da-252", lecture: "lecture-14", lectureNo: 14, question: "An advantage of drip irrigation is reduced disease and pest problems because:", options: ["The whole field is flooded", "The foliage is kept dry", "It uses high pressure", "It needs no filter"], correct: 1, explanation: "Drip irrigation maintains dry foliage (only part of the soil/root zone is wetted), which improves disease and pest management and limits weed growth.", difficulty: "medium" },
  { id: "d252l_095", subject: "da-252", lecture: "lecture-14", lectureNo: 14, question: "Sprinkler irrigation increases the production area mainly because it:", options: ["Needs more channels within the culturable command area", "Uses flooding", "Requires bunds", "Eliminates field channels and their maintenance"], correct: 3, explanation: "Sprinkler irrigation eliminates field channels and their maintenance (increasing the production area) and has no conveyance losses, which are about 35% in surface methods.", difficulty: "medium" },

  // ── Lecture 15: Pumps - Centrifugal & Submersible ──
  { id: "d252l_096", subject: "da-252", lecture: "lecture-15", lectureNo: 15, question: "A semi-open impeller in a centrifugal pump is most suitable for pumping:", options: ["Clear water only", "Air", "Viscous liquids", "Sand and gravel only"], correct: 2, explanation: "A semi-open impeller (shroud on one side) suits viscous liquids such as paper pulp, molasses and sewage water containing foreign materials.", difficulty: "hard" },
  { id: "d252l_097", subject: "da-252", lecture: "lecture-15", lectureNo: 15, question: "The casing of a centrifugal pump is:", options: ["A straight cylinder for high suction-lift installations while priming the centrifugal pump", "A strainer", "A foot valve", "A spiral-shaped cover of gradually increasing cross-section towards the discharge"], correct: 3, explanation: "The casing is a spiral-shaped cover with gradually increasing cross-sectional area towards the discharge end; it receives water from the impeller and discharges it.", difficulty: "medium" },
  { id: "d252l_098", subject: "da-252", lecture: "lecture-15", lectureNo: 15, question: "The delivery valve of a centrifugal pump:", options: ["Is kept open at the start", "Filters the water", "Is the same as the foot valve while priming the centrifugal pump", "Remains closed at the start of the pump"], correct: 3, explanation: "The delivery valve is a regulating valve on the delivery side; it remains closed at the start of the pump.", difficulty: "medium" },
  { id: "d252l_099", subject: "da-252", lecture: "lecture-15", lectureNo: 15, question: "An advantage that makes the centrifugal pump very popular is its:", options: ["Very high initial cost", "Low initial cost, simplicity and constant steady discharge", "Need for frequent priming during running for high suction-lift installations", "Inability to handle clear water"], correct: 1, explanation: "Centrifugal pumps are popular due to lower initial cost, flexibility, wide working range, simplicity of construction, constant steady discharge and easy operation/maintenance.", difficulty: "easy" },
  { id: "d252l_100", subject: "da-252", lecture: "lecture-15", lectureNo: 15, question: "In a submersible pump installation, no pump-house is required because:", options: ["The pump is on the surface in a reciprocating lift pump", "It needs no power", "The pump and motor assembly remain inside the well", "It uses gravity only"], correct: 2, explanation: "In a submersible pump no pump-house is required, as the pump and motor assembly remain inside the well; only a control panel is on the surface.", difficulty: "medium" },
  { id: "d252l_101", subject: "da-252", lecture: "lecture-15", lectureNo: 15, question: "Pumps are broadly grouped into indigenous water lifts and:", options: ["Solar panels", "Hand fans", "Highly efficient irrigation pumps", "Open channels at the deep-well turbine pump"], correct: 2, explanation: "Pumps are generally of two types: indigenous water lifts and highly efficient irrigation pumps (centrifugal, vertical turbine, submersible).", difficulty: "easy" },
  { id: "d252l_102", subject: "da-252", lecture: "lecture-15", lectureNo: 15, question: "Couplings in a centrifugal pumping unit are used to connect the pump shaft to the:", options: ["Foot valve", "Strainer", "Delivery pipe while priming the centrifugal pump", "Motor or engine shaft"], correct: 3, explanation: "Couplings are most commonly used to connect the pump shaft to the motor or engine shaft; bearings keep the shaft in correct position.", difficulty: "easy" },

  // ── Lecture 16: Greenhouse Technology ──
  { id: "d252l_103", subject: "da-252", lecture: "lecture-16", lectureNo: 16, question: "The lean-to type greenhouse is generally limited to single or double-row plant benches with a total width of about:", options: ["20 to 30 feet", "7 to 12 feet", "50 feet", "1 to 2 feet"], correct: 1, explanation: "The lean-to greenhouse is limited to single or double-row benches with a total width of 7 to 12 feet and can be as long as the building it is attached to.", difficulty: "medium" },
  { id: "d252l_104", subject: "da-252", lecture: "lecture-16", lectureNo: 16, question: "For a single-span even-span greenhouse, the span generally varies from:", options: ["50 to 60 m", "20 to 30 m", "0.5 to 1 m", "5 to 9 m"], correct: 3, explanation: "For a single-span even-span greenhouse the span generally varies from 5 to 9 m, the length around 24 m and the height from 2.5 to 4.3 m.", difficulty: "hard" },
  { id: "d252l_105", subject: "da-252", lecture: "lecture-16", lectureNo: 16, question: "UV light, which is largely harmful to plants, lies in the wavelength range of:", options: ["400 to 700 nm used while plotting the map to scale", "Less than 400 nm", "700 to 750 nm", "Above 1000 nm"], correct: 1, explanation: "UV light is in the shorter-wavelength range (less than 400 nm); large quantities are harmful, and glass screens are opaque to most UV light.", difficulty: "medium" },
  { id: "d252l_106", subject: "da-252", lecture: "lecture-16", lectureNo: 16, question: "When plants are grown only under blue (shorter-wavelength) light, the growth is:", options: ["Soft and tall applied in plane-table traversing", "Unaffected", "Retarded, hard and dark in colour", "Very rapid"], correct: 2, explanation: "Under blue light (shorter wavelength) growth is retarded and the plant becomes hard and dark in colour; under red light growth is soft with long internodes (tall plants).", difficulty: "hard" },
  { id: "d252l_107", subject: "da-252", lecture: "lecture-16", lectureNo: 16, question: "Greenhouse crops are generally grown at a day temperature higher than the night temperature by about:", options: ["30°C", "20°C", "0°C (the same) under shade-net protected cultivation", "3 to 6°C on cloudy days"], correct: 3, explanation: "As a general rule, greenhouse crops are grown at a day temperature 3 to 6°C higher than the night temperature on cloudy days and about 8°C higher on clear days.", difficulty: "medium" },
  { id: "d252l_108", subject: "da-252", lecture: "lecture-16", lectureNo: 16, question: "Besides excelsior and cellulose, another material that can be used as a greenhouse cooling pad is:", options: ["Khus-khus grass mats", "Steel sheets in fan-and-pad cooled greenhouses", "Glass panes", "Concrete"], correct: 0, explanation: "Cooling pads are commonly made of excelsior (wood fibre) or cross-fluted cellulose; khus-khus grass mats can also be used as cooling pads.", difficulty: "medium" },
  { id: "d252l_109", subject: "da-252", lecture: "lecture-16", lectureNo: 16, question: "A dedicated greenhouse microprocessor can typically control up to about:", options: ["20 devices", "2 devices", "200 devices", "2000 devices"], correct: 0, explanation: "A dedicated microprocessor (a simple computer) has more output connections than a thermostat and can control up to about 20 devices, often using a thermistor for temperature sensing.", difficulty: "hard" },
  { id: "d252l_110", subject: "da-252", lecture: "lecture-16", lectureNo: 16, question: "A greenhouse for active cooling draws large volumes of cooled air using either an evaporative cooling pad with fan or:", options: ["Open burning", "Fog cooling", "Compressed air", "Heating coils"], correct: 1, explanation: "A greenhouse for active cooling uses either an evaporative cooling pad with a fan or fog cooling, and is designed to permit a roof opening of about 40% (sometimes nearly 100%).", difficulty: "medium" },
];
